const spellState = new WeakMap();          // external, identity-keyed state
export function attachSpellCheck(doc, state) { spellState.set(doc, state); }
export function spellCheck(doc, text) {
  const state = spellState.get(doc);
  if (!state?.enabled) return undefined;   // capability may be absent
  return state.dictionary.check(text);
}
